package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

var (
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity (tokens), refill rate
// (tokens per second), and clock. If clock is nil, the real clock is used.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, refilling the bucket based
// on elapsed time. It consumes tokens atomically if available.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.capacity {
		t = l.capacity
	}
	return t
}
