// limiter.go
package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // bucket capacity
	tokens   float64   // current tokens
	lastTime time.Time // last refill time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full. clock may be nil for the real clock.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("limiter: burst must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		rate:     rate,
		burst:    burst,
		tokens:   float64(burst),
		lastTime: now,
		clock:    clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool {
	return l.AllowN(time.Time{}, 1)
}

// AllowN reports whether n tokens are available at time now. If now is the
// zero time, the limiter's clock is used.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.lastTime = now
	}
	if n < 0 || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now.
func (l *Limiter) RetryAfter(n int) time.Duration {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.lastTime = now
	}
	if n <= 0 || float64(n) <= l.tokens {
		return 0
	}
	need := float64(n) - l.tokens
	return time.Duration(need / l.rate * float64(time.Second))
}
